AI_MODEL = os.getenv("AI_MODEL", "")
INTIM_MODEL = os.getenv("INTIM_MODEL", "")

# Reasoning-модели (например, DeepSeek с тегом Reasoning) тратят время на скрытые "мысли"
# до видимого ответа и могут не уложиться в короткий таймаут по умолчанию — даём с запасом.
AI_REQUEST_TIMEOUT = 100

# Kept for backwards-compatible diagnostic snapshots; routing itself is uncached.
_model_cache = {}


def _fetch_model_catalog():
    try:
        return [m.id for m in client.models.list().data]
    except Exception as e:
        logging.warning(f"Не удалось получить список моделей provod.ai: {e}")
        return []


def resolve_model(cache_key):
    """Read the saved route for each new request, with no cached/fuzzy fallback."""
    return model_routing.selected(user_data.get('__settings__', {}), cache_key)


def invalidate_model_cache(cache_key):
    _model_cache.pop(cache_key, None)


def call_ai(explicit_model, cache_key, **kwargs):
    """Freeze the saved model for this turn, including timeout/language retries.

    Model changes affect subsequent requests, never an answer already in flight.
    """
    if cache_key in model_routing.ROUTES:
        explicit_model = resolve_model(cache_key)
    if kwargs.get("messages"):
        # В истории бывают служебные поля для мини-приложения (реакция, карточка подарка) -- в ИИ только роль и текст.
        kwargs["messages"] = [{"role": m["role"], "content": m["content"]} for m in kwargs["messages"]]
    response = _call_ai_raw(explicit_model, cache_key, **kwargs)
    # Защита от «каши из языков»: DeepSeek Flash иногда вставляет посреди русского ответа иероглифы или
    # целые английские фразы (по фидбэку). Тогда пробуем ещё раз чуть «холоднее», а если снова --
    # вырезаем иероглифы, чтобы до пользователя они не дошли.
    try:
        text = response.choices[0].message.content or ""
    except (AttributeError, IndexError):
        return response
    if not _language_glitch(text):
        return response
    logging.warning("Ответ ИИ со смешением языков, повторяем запрос")
    retry_kwargs = dict(kwargs)
    retry_kwargs["temperature"] = max(0.5, (kwargs.get("temperature") or 0.9) - 0.25)
    try:
        retry = _call_ai_raw(explicit_model, cache_key, **retry_kwargs)
        retry_text = retry.choices[0].message.content or ""
        if retry_text.strip() and not _language_glitch(retry_text):
            return retry
        if retry_text.strip():
            response, text = retry, retry_text
    except Exception as e:
        logging.warning(f"Повтор после смешения языков не удался: {e}")
    if re.search('[а-яА-ЯёЁ]',text) and LATIN_PHRASE_RE.search(text):
        try:
            repaired=_call_ai_raw(explicit_model,cache_key,messages=[{'role':'system','content':'Исправь только случайные иностранные вставки в русском тексте: переведи их на русский. Сохрани смысл, стиль, формат и длину. Ничего не добавляй. Верни только исправленный текст.'},{'role':'user','content':text}],temperature=0.2,max_tokens=kwargs.get('max_tokens',750))
            fixed=repaired.choices[0].message.content or ''
            if fixed.strip() and not CJK_RE.search(fixed):text=fixed
        except Exception as exc:logging.warning('Language repair: %s',type(exc).__name__)
    if re.search('[а-яА-ЯёЁ]',text):
        fixes={'actually':'на самом деле','literally':'буквально','honestly':'честно','anyway':'в любом случае','because':'потому что','whatever':'как угодно','sometimes':'иногда','really':'правда','maybe':'может быть','sorry':'извини','instead':'вместо этого'}
        text=re.sub(r'\b(?:'+ '|'.join(fixes)+r')\b',lambda m:fixes[m.group().lower()],text,flags=re.I)
    response.choices[0].message.content = CJK_RE.sub("", text)
    return response


CJK_RE = re.compile(r"[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uac00-\ud7af\uff00-\uffef]+")
LATIN_PHRASE_RE = re.compile(r"\b[A-Za-z']{2,}(?:[ ,]+[A-Za-z']{2,}){1,}\b")


def _language_glitch(text):
    """Иероглифы в любом ответе, либо английская фраза из 2+ слов внутри в основном кириллического текста."""
    if CJK_RE.search(text):
        return True
    letters = [ch for ch in text if ch.isalpha()]
    cyr = sum(1 for ch in letters if "а" <= ch.lower() <= "я" or ch.lower() == "ё")
    return bool(letters) and cyr / len(letters) > 0.5 and bool(LATIN_PHRASE_RE.search(text) or re.search(r'\b(?:actually|literally|honestly|anyway|because|whatever|sometimes|really|maybe|sorry|instead)\b',text,re.I))


def _call_ai_raw(explicit_model, cache_key, **kwargs):
    model = explicit_model or resolve_model(cache_key)
    kwargs.setdefault("timeout", AI_REQUEST_TIMEOUT)
    try:
        return client.chat.completions.create(model=model, **kwargs)
    except Exception as e:
        if isinstance(e, APITimeoutError):
            logging.warning(f"Таймаут запроса к {model} ({AI_REQUEST_TIMEOUT}с), пробуем ещё раз")
            return client.chat.completions.create(model=model, **kwargs)
        raise

