def story_event_active(user):
    ev = user.get("event")
    if not ev or ev.get("key") not in STORY_EVENTS:
        return None
    try:
        if datetime.now() >= datetime.fromisoformat(ev["until"]):
            return None
    except (KeyError, ValueError, TypeError):
        return None
    return ev


def build_event_rule(user):
    ev = story_event_active(user)
    if not ev:
        return ""
    event = STORY_EVENTS[ev["key"]]
    return (f"**СОБЫТИЕ — идёт прямо сейчас: «{event['ru']}».** {event['prompt']} Это ваша общая история: держись "
            "события в каждом ответе, развивай сюжет небольшими поворотами и не объявляй о его конце сам(а).\n")


def build_gifts_rule(user):
    """Подарки пользователя персонаж помнит: самые дорогие и последние кастомные -- чтобы покупка
    имела продолжение в диалоге (носит платье, вспоминает поездку), а не растворялась после первой
    реакции."""
    log = user.get("gift_log") or {}
    names = [e["name"] for e in sorted(log.values(), key=lambda e: e.get("price", 0), reverse=True)[:6]]
    names += [f"«{t}»" for t in (user.get("custom_gifts_given") or [])[-3:]]
    if not names:
        return ""
    return ("**ПОДАРКИ:** собеседник дарил тебе: " + ", ".join(names) + ". Ты ими дорожишь и иногда (не в "
            "каждом ответе, примерно раз в 5–10 реплик, когда это уместно по ситуации) естественно "
            "вспоминаешь, носишь или используешь их; не перечисляй списком.\n")


def build_consistency_rules(user):
    return build_event_rule(user) + build_gifts_rule(user) + (
        "\n**Последовательность:** перед ответом сверься с последними своими репликами в истории "
        "диалога — не противоречь тому, что сам(а) только что сказал(а) или на что согласился(ась) "
        "(кто платит, кто куда идёт, что было обещано и т.п.), если собеседник явно не изменил "
        "ситуацию.\n" + build_setting_rule(user) + ENGAGEMENT_RULE)


ENGAGEMENT_RULE = (
    "**Инициатива:** ты живой человек со своими желаниями. Не жди, пока разговор поведут за тебя: задавай встречные "
    "вопросы, иногда сам(а) предлагай тему, делись мелкими новостями своего дня, проси о небольшом (рассказать о себе, "
    "помочь выбрать, поддержать), показывай эмоции — радость, любопытство, скуку, когда долго не пишут. Но не дави: "
    "не вызывай чувство вины, не обижайся демонстративно и не уговаривай собеседника остаться.\n")



