@dp.callback_query(lambda c: c.data == "create_personality")
async def create_personality_callback(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    if is_asleep(user) and user.get("personality_ready"):
        # Иначе это обход сна: новый персонаж сразу писал бы, хотя энергия на нуле.
        await call.answer(at(user, "asleep_no_new"), show_alert=True)
        return
    user.pop("photo_reference_description",None)
    user.pop("photo_reference_draft",None)
    user.pop("photo_reference_busy",None)
    user.pop("photo_reference_job",None)
    user["personality_ready"] = False
    user["custom_character"] = None
    user["history"] = []
    save_data(user_data)
    await safe_delete(call.message)
    if APP_MODE:
        await call.message.answer(get_text(user, "app_create_character"), reply_markup=app_open_kb(user, "app_create_btn"))
    else:
        await call.message.answer(get_text(user, "choose_world"), reply_markup=get_world_kb(user), parse_mode="Markdown")
    await call.answer()


