# ---------- CryptoBot (Crypto Pay API) ----------
async def _crypto_request(method, path, **kwargs):
    async with httpx.AsyncClient(timeout=20) as client:
        response = await client.request(
            method, f"{CRYPTO_PAY_API}/{path}",
            headers={"Crypto-Pay-API-Token": CRYPTO_PAY_TOKEN}, **kwargs
        )
    return response.json()


async def create_crypto_invoice(user_id, payload, description):
    data = await _crypto_request(
        "POST", "createInvoice",
        json={
            "currency_type": "fiat",
            "fiat": "USD",
            "amount": f"{PRODUCTS[payload]['usd']:.2f}",
            "description": description[:1024],
            "payload": f"{user_id}:{payload}",
            "expires_in": PAYMENT_TIMEOUT_MINUTES * 60,
        },
    )
    if not data.get("ok"):
        raise RuntimeError(f"CryptoBot createInvoice: {data}")
    result = data["result"]
    url = result.get("bot_invoice_url") or result.get("mini_app_invoice_url") or result.get("pay_url")
    return str(result["invoice_id"]), url


async def check_crypto_invoice(invoice_id):
    data = await _crypto_request("GET", "getInvoices", params={"invoice_ids": invoice_id})
    if not data.get("ok"):
        return None
    items = (data.get("result") or {}).get("items") or []
    return items[0].get("status") if items else None


# ---------- Lava (business API) ----------
def _lava_call_body(body):
    """Lava подписывает ровно ту строку тела, которую мы отправляем,
    поэтому сериализуем один раз и шлём как есть."""
    raw = json.dumps(body, separators=(",", ":"), ensure_ascii=False)
    signature = hmac.new(LAVA_SECRET_KEY.encode(), raw.encode(), hashlib.sha256).hexdigest()
    headers = {"Signature": signature, "Accept": "application/json",
               "Content-Type": "application/json"}
    return raw, headers


async def create_lava_invoice(user_id, payload, description):
    order_id = f"{user_id}-{payload}-{int(datetime.now().timestamp())}"
    raw, headers = _lava_call_body({
        "sum": round(float(PRODUCTS[payload]["rub"]), 2),
        "orderId": order_id,
        "shopId": LAVA_SHOP_ID,
        "comment": description[:250],
    })
    async with httpx.AsyncClient(timeout=20) as client:
        response = await client.post(f"{LAVA_API}/invoice/create", content=raw.encode(), headers=headers)
    data = response.json()
    url = (data.get("data") or {}).get("url")
    if not url:
        raise RuntimeError(f"Lava invoice/create: {data}")
    return order_id, url


async def check_lava_invoice(order_id):
    raw, headers = _lava_call_body({"shopId": LAVA_SHOP_ID, "orderId": order_id})
    async with httpx.AsyncClient(timeout=20) as client:
        response = await client.post(f"{LAVA_API}/invoice/status", content=raw.encode(), headers=headers)
    data = response.json()
    return (data.get("data") or {}).get("status")


# ---------- Platega ----------
def product_rub(payload, user=None):
    """Цена картой: от цены в звёздах для этого пользователя (распродажи и купон учитываются так же)."""
    if payload in SUBSCRIPTION_PRICES:
        if payload=='subscribe_pro' and datetime.now().isoformat()<PHOTO_PROMO_UNTIL:return 300
        return SUBSCRIPTION_PRICES[payload][1]
    return max(10, int(round(product_stars(payload, user) * RUB_PER_STAR)))


def _platega_headers():
    return {"X-MerchantId": PLATEGA_MERCHANT_ID, "X-Secret": PLATEGA_SECRET, "Content-Type": "application/json"}


async def create_platega_invoice(user, user_id, payload, description):
    body = {
        "paymentDetails": {"amount": product_rub(payload, user), "currency": "RUB"},
        "description": description[:250],
        "return": PLATEGA_RETURN_URL,
        "failedUrl": PLATEGA_RETURN_URL,
        "payload": f"{user_id}:{payload}",
        "metadata": {"userId": str(user_id), "userName": str(user.get("username") or user_id)},
    }
    async with httpx.AsyncClient(timeout=20) as client:
        response = await client.post(f"{PLATEGA_API}/v2/transaction/process", json=body, headers=_platega_headers())
    data = response.json()
    if not data.get("url") or not data.get("transactionId"):
        raise RuntimeError(f"Platega transaction/process {response.status_code}: {data}")
    return data["transactionId"], data["url"]


async def check_platega_invoice(transaction_id):
    async with httpx.AsyncClient(timeout=20) as client:
        response = await client.get(f"{PLATEGA_API}/transaction/{transaction_id}", headers=_platega_headers())
    return (response.json() or {}).get("status")


async def finish_external_payment(user, user_id, item):
    """Выдача товара по внешнему платежу (Platega/Lava/CryptoBot) + купон, как у оплаты звёздами."""
    if item.get("coupon") and coupon_active(user):
        user["coupon"] = None
        save_data(user_data)
        await bot.send_message(user_id, get_text(user, "coupon_used"))
    first_purchase = not user.get("first_purchase_done")
    await grant_product(user, item["payload"], user_id)
    if first_purchase:
        await grant_first_purchase_coupon(user, user_id)


async def platega_callback_handler(request):
    """Колбэк Platega о смене статуса: подлинность -- по X-MerchantId/X-Secret (так в их документации)."""
    if not PLATEGA_SECRET or request.headers.get("X-Secret") != PLATEGA_SECRET \
            or request.headers.get("X-MerchantId") != PLATEGA_MERCHANT_ID:
        return web.Response(status=403)
    try:
        body = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.Response(status=400)
    transaction_id = body.get("id")
    status = (body.get("status") or "").lower()
    for user_id, user in list(user_data.items()):
        for item in list(user.get("pending_payments") or []):
            if item.get("provider") != "platega" or item.get("invoice_id") != transaction_id:
                continue
            user["pending_payments"].remove(item)  # до await -- повтор колбэка/опрос не выдадут товар дважды
            save_data(user_data)
            if status in PAID_STATUSES:
                try:
                    await finish_external_payment(user, int(user_id), item)
                except Exception as e:
                    logging.error(f"Platega: не удалось выдать {item['payload']} для {user_id}: {e}")
            elif status not in DEAD_STATUSES:
                user["pending_payments"].append(item)  # неизвестный статус -- ждём дальше
                save_data(user_data)
            return web.Response(text="ok")
    return web.Response(text="ok")


# ---------- общая часть ----------
PAID_STATUSES = {"paid", "success", "successful", "completed", "confirmed"}
DEAD_STATUSES = {"expired", "cancel", "cancelled", "canceled", "failed", "error", "chargebacked"}


def add_pending_payment(user, provider, invoice_id, payload, coupon=False):
    pending = user.setdefault("pending_payments", [])
    pending.append({
        "provider": provider,
        "invoice_id": invoice_id,
        "payload": payload,
        "created_at": datetime.now().isoformat(),
        "coupon": coupon,  # счёт выставлен с персональной скидкой -- при оплате купон гасим
    })
    save_data(user_data)


FIRST_SUBSCRIPTION_BONUS_BUCKS = 1000  # было 150 — увеличено по просьбе, разовая премия за самую
# первую покупку ЛЮБОЙ подписки (см. ever_subscribed ниже) — по фидбэку заменяет часть ценности
# прежнего ежедневного баксового стипенда (было BUCKS_DAILY_STIPEND) разовым бонусом в момент
# покупки; вторая половина замены — тиерный множитель с заработка на работе, см.
# work_earnings_multiplier/WORK_MULTIPLIER.
FIRST_SUBSCRIPTION_BONUS_ENERGIZERS = 0  # по фидбэку "хотелось бы интереснее, чем просто баксы" —
# добавили энергетики (мгновенно применимая плюшка) и бесплатную горячую сцену ниже, а не только
# циферки баланса.
FIRST_SUBSCRIPTION_BONUS_SCENES = 2

# Реферальные награды (по фидбэку: раньше было много энергетиков и мало баксов).
REFERRAL_INVITER_BUCKS = 2000
REFERRAL_INVITER_ENERGIZERS = 1
REFERRAL_INVITER_SCENES = 2
REFERRAL_INVITEE_BUCKS = 1500
REFERRAL_INVITEE_SCENES = 0
REFERRAL_INVITEE_SPINS = 0  # разовый бонусный прокрут, не сгорает с дневным лимитом (bonus_spins)


def grant_first_subscription_bonus(user):
    """Разовый бонус за самую первую покупку ЛЮБОЙ подписки — баксы + энергетики + горячая
    сцена, не только баксы (см. ever_subscribed в вызывающем коде). Общая функция вместо
    копирования одного и того же блока в subscribe_pro/subscribe_super/subscribe_elite."""
    user["bucks"] = user.get("bucks", 0) + FIRST_SUBSCRIPTION_BONUS_BUCKS
    user["energizers"] = user.get("energizers", 0) + FIRST_SUBSCRIPTION_BONUS_ENERGIZERS
    user["intim_scenes"] = user.get("intim_scenes", 0) + FIRST_SUBSCRIPTION_BONUS_SCENES


async def grant_product(user, payload, chat_id):
    """Единая выдача товара: и для Stars, и для внешних платёжек.
    Раньше эта логика жила прямо в payment_success и работала только для Stars."""
    user["has_purchased"] = True

    photo_wallet.ensure(user)
    if payload=='farm_fertilizer':
        farm_upgrade.grant(user);save_data(user_data)
    elif payload=='avatar_generate':
        user['portrait_credits']=user.get('portrait_credits',0)+1
        save_data(user_data)
    elif payload in photo_wallet.ALL_PACKS or payload=='scene_photo':
        photo_wallet.grant(user,photo_wallet.ALL_PACKS[payload][0] if payload in photo_wallet.ALL_PACKS else 1)
        if payload=='scene_photo':user['intim_scenes']=user.get('intim_scenes',0)+1
        save_data(user_data)
    elif payload in WEEKLY_SUBSCRIPTIONS:
        grant_subscription_days(user, WEEKLY_SUBSCRIPTIONS[payload][0], 7)
        user['last_daily_reset'] = None
        _reset_daily_quota_if_needed(user)
        if not user.get('ever_subscribed'):
            grant_first_subscription_bonus(user)
        user['ever_subscribed'] = True
        save_data(user_data)
        await bot.send_message(chat_id, WEEKLY_SUBSCRIPTIONS[payload][0].replace('_', ' ').upper() + ' · 7 ' + ('дней' if user.get('lang') == 'ru' else 'days'))
    elif payload in BUCKS_PACKS:
        user["bucks"] = user.get("bucks", 0) + BUCKS_PACKS[payload]
        save_data(user_data)
    elif payload in ENERGIZER_PACKS:
        # Покупается только из Shop Mini App через openInvoice (см. api_shop_energizer_invoice_handler) —
        # как и spin_paid_webapp, не дублируем отдельным сообщением в чат: обновлённый баланс
        # и так виден прямо в магазине после обновления состояния.
        user["energizers"] = user.get("energizers", 0) + ENERGIZER_PACKS[payload]["amount"]
        save_data(user_data)
    elif payload == "subscribe_pro":
        grant_subscription_days(user, "pro", 30)
        # Форсируем полный пересчёт дневных плюшек (сообщения, баксы, энергетики, бесплатные
        # сцены) прямо сейчас, а не только с завтрашнего дня — раньше здесь просто вручную
        # проставлялись daily_messages/last_daily_reset, и бонус баксов/энергетиков в день
        # покупки просто пропадал.
        user["last_daily_reset"] = None
        _reset_daily_quota_if_needed(user)
        first_time_sub = not user.get("ever_subscribed")
        user["ever_subscribed"] = True
        if first_time_sub:
            grant_first_subscription_bonus(user)
        save_data(user_data)
        await bot.send_message(chat_id, get_text(user, "payment_pro_success"))
        if first_time_sub:
            await bot.send_message(chat_id, get_text(user, "first_subscription_bonus_alert", bucks=FIRST_SUBSCRIPTION_BONUS_BUCKS, energizers=FIRST_SUBSCRIPTION_BONUS_ENERGIZERS, scenes=FIRST_SUBSCRIPTION_BONUS_SCENES))
    elif payload == "subscribe_super":
        grant_subscription_days(user, "super_pro", 30)
        user["last_daily_reset"] = None
        _reset_daily_quota_if_needed(user)
        first_time_sub = not user.get("ever_subscribed")
        user["ever_subscribed"] = True
        if first_time_sub:
            grant_first_subscription_bonus(user)
        save_data(user_data)
        await bot.send_message(chat_id, get_text(user, "payment_super_success"))
        if first_time_sub:
            await bot.send_message(chat_id, get_text(user, "first_subscription_bonus_alert", bucks=FIRST_SUBSCRIPTION_BONUS_BUCKS, energizers=FIRST_SUBSCRIPTION_BONUS_ENERGIZERS, scenes=FIRST_SUBSCRIPTION_BONUS_SCENES))
    elif payload == "subscribe_elite":
        grant_subscription_days(user, "elite", 30)
        user["last_daily_reset"] = None
        _reset_daily_quota_if_needed(user)
        first_time_sub = not user.get("ever_subscribed")
        user["ever_subscribed"] = True
        if first_time_sub:
            grant_first_subscription_bonus(user)
        save_data(user_data)
        await bot.send_message(chat_id, get_text(user, "payment_elite_success"))
        if first_time_sub:
            await bot.send_message(chat_id, get_text(user, "first_subscription_bonus_alert", bucks=FIRST_SUBSCRIPTION_BONUS_BUCKS, energizers=FIRST_SUBSCRIPTION_BONUS_ENERGIZERS, scenes=FIRST_SUBSCRIPTION_BONUS_SCENES))
    elif payload in ('upgrade_to_super','upgrade_to_elite'):
        quote=premium_rules.upgrade(user)
        if quote and quote['payload']==payload:
            user['subscription']['level']=quote['target']
            user['energizers']=user.get('energizers',0)+max(0,ENERGIZERS_DAILY_STIPEND[quote['target']]-ENERGIZERS_DAILY_STIPEND[quote['source']])
            if not user.get('ever_subscribed'):grant_first_subscription_bonus(user);user['ever_subscribed']=True
            photo_wallet.grant(user,quote['photos'],quote['expires_at'])
            save_data(user_data)
            await bot.send_message(chat_id,'✅ '+quote['target'].replace('_',' ').upper()+' до '+datetime.fromisoformat(quote['expires_at']).strftime('%d.%m.%Y %H:%M')+'. Срок сохранён.')
    elif payload == "intim_scene":
        user["intim_scenes"] = user.get("intim_scenes", 0) + 1
        save_data(user_data)
        await bot.send_message(chat_id, get_text(user, "payment_intim_success"))
    elif payload == "wake_now":
        user["energy"] = ENERGY_MAX
        user["sleep_until"] = None
        save_data(user_data)
        await bot.send_message(chat_id, get_text(user, "woken_up"))
    elif payload == "defibrillator":
        # Ничего не восстанавливаем — "смерть" была лишь флагом, ничего физически не стёрлось
        # (см. kill_character), так что просто снимаем блокировку чата.
        user.update(dead=False,energy=ENERGY_MAX,satiety=SATIETY_MAX,water=WATER_MAX,sleep_until=None,water_zero_since=None,illness=None,illness_since=None)
        save_data(user_data)
        await bot.send_message(chat_id, get_text(user, "defibrillator_success"))
    elif payload == "spin_luck":
        base = datetime.now()
        try:
            current = datetime.fromisoformat(user.get("spin_luck_until") or "")
            if current > base:
                base = current
        except (ValueError, TypeError):
            pass
        user["spin_luck_until"] = (base + timedelta(hours=SPIN_LUCK_HOURS)).isoformat()
        save_data(user_data)
    elif payload == "spin_paid_20":
        await spin_result(chat_id, user, free=False)
    elif payload == "spin_paid_webapp":
        # Прокрут уже анимируется в самом Mini App (см. SPIN_PAGE_HTML) — здесь только
        # начисляем приз и кладём результат туда, где его подберёт опрос
        # api_spin_paid_result_handler. Раньше ещё дублировали результат отдельным сообщением в
        # чат — убрали по просьбе пользователя: в мини-аппе итак всё видно, а то сообщение к тому
        # же слалось без parse_mode="Markdown", так что звёздочки **так** оставались буквальными.
        # Раньше приз крутился прямо здесь, а Mini App ждал его ~14 с опросом -- если Telegram присылал
        # подтверждение оплаты позже, колесо так и не крутилось, хотя звёзды списались (баг из фидбэка).
        # Теперь покупка просто добавляет прокрут, и он сразу виден на кнопке «Крутить».
        user["bonus_spins"] = user.get("bonus_spins", 0) + 1
        save_data(user_data)
        await bot.send_message(chat_id, get_text(user, "webapp_spin_paid_ready"))


async def retry_star_refunds(user,user_id):
    for charge in list(user.get('pending_star_refunds') or []):
        try:await bot.refund_star_payment(user_id=user_id,telegram_payment_charge_id=charge)
        except Exception as exc:
            if 'already' not in str(exc).lower():logging.warning('Stars refund pending for %s: %s',user_id,type(exc).__name__);continue
        if charge in user.get('pending_star_refunds',[]):user['pending_star_refunds'].remove(charge)
        save_data(user_data)


async def check_pending_payments():
    """CryptoBot и Lava подтверждают оплату вебхуками, но у бота нет
    веб-сервера (он на long polling), поэтому просто опрашиваем статусы."""
    while True:
        await asyncio.sleep(30)
        try:
            sync_data()
            for user_id, user in list(user_data.items()):
                if str(user_id).isdigit() and user.get('pending_star_refunds'):await retry_star_refunds(user,int(user_id))
                for item in list(user.get("pending_payments") or []):
                    provider = item.get("provider")
                    try:
                        if provider == "crypto":
                            status = await check_crypto_invoice(item["invoice_id"])
                        elif provider == "lava":
                            status = await check_lava_invoice(item["invoice_id"])
                        elif provider == "platega":
                            status = await check_platega_invoice(item["invoice_id"])
                        else:
                            status = None
                    except Exception as e:
                        logging.warning(f"Проверка платежа {provider} {item.get('invoice_id')}: {e}")
                        continue

                    expired = False
                    try:
                        created = datetime.fromisoformat(item["created_at"])
                        expired = (datetime.now() - created).total_seconds() > PAYMENT_TIMEOUT_MINUTES * 60
                    except Exception:
                        expired = True

                    status_key = (status or "").lower()
                    if status_key in PAID_STATUSES:
                        user["pending_payments"].remove(item)
                        save_data(user_data)
                        try:
                            await finish_external_payment(user, int(user_id), item)
                        except Exception as e:
                            logging.error(f"Не удалось выдать товар {item['payload']} для {user_id}: {e}")
                    elif status_key in DEAD_STATUSES or expired:
                        user["pending_payments"].remove(item)
                        save_data(user_data)
        except Exception as e:
            logging.error(f"Ошибка проверки платежей: {e}")


async def send_stars_invoice(chat_id, user, payload):
    title, description, label = product_invoice_texts(user, payload)
    await bot.send_invoice(
        chat_id=chat_id,
        title=title,
        description=description,
        payload=payload,
        provider_token="",
        currency="XTR",
        prices=[LabeledPrice(label=label, amount=product_stars(payload, user))],
    )


async def start_payment(call: types.CallbackQuery, user, method, payload):
    chat_id = call.message.chat.id
    title, description, _ = product_invoice_texts(user, payload)

    if method == "stars":
        await send_stars_invoice(chat_id, user, payload)
        return

    try:
        if method == "crypto":
            invoice_id, url = await create_crypto_invoice(call.from_user.id, payload, description)
        elif method == "lava":
            invoice_id, url = await create_lava_invoice(call.from_user.id, payload, description)
        elif method == "platega":
            invoice_id, url = await create_platega_invoice(user, call.from_user.id, payload, description)
        else:
            return
    except Exception as e:
        logging.error(f"Счёт {method} для {payload}: {e}")
        await call.message.answer(get_text(user, "pay_error"))
        return

    add_pending_payment(user, method, invoice_id, payload,
                        coupon=method == "platega" and coupon_active(user) and product_stars(payload, user) < product_stars(payload))
    keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=get_text(user, "pay_open_invoice"), url=url, style="success")]
    ])
    await call.message.answer(f"{title}\n\n{get_text(user, 'pay_invoice_ready')}", reply_markup=keyboard)


def get_payment_methods_kb(user, payload):
    prices = PRODUCTS[payload]
    labels = {
        "stars": get_text(user, "pay_stars", amount=product_stars(payload, user)),
        "crypto": get_text(user, "pay_crypto", amount=prices["usd"]),
        "lava": get_text(user, "pay_lava", amount=prices["rub"]),
        "platega": get_text(user, "pay_platega", amount=product_rub(payload, user)),
    }
    rows = [[InlineKeyboardButton(text=labels[method], callback_data=f"pay:{method}:{payload}", style="success")]
            for method in available_payment_methods(payload)]
    rows.append([InlineKeyboardButton(text=get_text(user, "back_to_profile"), callback_data="back_to_profile", style="danger")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def payment_blocked_reason(user, payload):
    """Те же проверки, что раньше висели на каждой кнопке покупки."""
    if payload in ("subscribe_pro", "subscribe_super", "subscribe_elite", *WEEKLY_SUBSCRIPTIONS) and has_active_subscription(user):
        return get_text(user, "already_subscribed_alert")
    if payload in ('upgrade_to_super','upgrade_to_elite'):
        quote=premium_rules.upgrade(user)
        if not quote or quote['payload']!=payload:return 'Это улучшение сейчас недоступно. Обнови раздел покупок.'
    return None


@dp.callback_query(lambda c: c.data.startswith("buy:"))
async def buy_product(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    payload = call.data.split(":", 1)[1]
    if payload not in PRODUCTS:
        await call.answer()
        return

    blocked = payment_blocked_reason(user, payload)
    if blocked:
        await call.answer(blocked, show_alert=True)
        return

    methods = available_payment_methods(payload)
    if len(methods) == 1:
        # выбирать не из чего — сразу счёт, как было раньше
        await start_payment(call, user, methods[0], payload)
    else:
        await call.message.answer(get_text(user, "choose_payment"),
                                  reply_markup=get_payment_methods_kb(user, payload),
                                  parse_mode="Markdown")
    await call.answer()


@dp.callback_query(lambda c: c.data.startswith("pay:"))
async def pay_with_method(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    _, method, payload = call.data.split(":", 2)
    # available_payment_methods(payload), а не голый is_method_enabled(method) — вторая только
    # проверяет, что Lava вообще настроена, но не что она разрешена ИМЕННО для этого товара;
    # без этой проверки старая/подделанная callback-кнопка могла бы провести Lava-оплату
    # 18+-товара в обход того, что показывается в клавиатуре.
    if payload not in PRODUCTS or method not in available_payment_methods(payload):
        await call.answer()
        return

    blocked = payment_blocked_reason(user, payload)
    if blocked:
        await call.answer(blocked, show_alert=True)
        return

    await start_payment(call, user, method, payload)
    await call.answer()


@dp.pre_checkout_query()
async def pre_checkout(query: types.PreCheckoutQuery):
    valid = query.invoice_payload in PRODUCTS and query.currency == "XTR"
    if valid and query.invoice_payload=='farm_fertilizer':
        valid=query.total_amount==farm_upgrade.STARS and farm_upgrade.snapshot(get_user(query.from_user.id))['available']
    if valid and query.invoice_payload in ('upgrade_to_super','upgrade_to_elite'):
        buyer=get_user(query.from_user.id)
        valid=not payment_blocked_reason(buyer,query.invoice_payload) and query.total_amount>=product_stars(query.invoice_payload,buyer)
    await bot.answer_pre_checkout_query(query.id, ok=valid, error_message=None if valid else "Invalid invoice")


@dp.message(lambda m: m.successful_payment)
async def payment_success(message: types.Message):
    user = get_user(message.from_user.id)
    payment = message.successful_payment
    payload = payment.invoice_payload
    charge = payment.telegram_payment_charge_id
    charges = user.setdefault("processed_star_charges", [])
    if charge in charges:
        return
    if payload not in PRODUCTS or payment.currency != "XTR":
        logging.error("Unexpected successful payment payload/currency for user %s", message.from_user.id)
        return
    if payload=='farm_fertilizer' and (payment.total_amount!=farm_upgrade.STARS or not farm_upgrade.snapshot(user)['available']):
        charges.append(charge);user.setdefault('pending_star_refunds',[]).append(charge);save_data(user_data)
        await retry_star_refunds(user,message.from_user.id);return
    if payload in ('upgrade_to_super','upgrade_to_elite') and payment_blocked_reason(user,payload):
        charges.append(charge);user.setdefault('pending_star_refunds',[]).append(charge);save_data(user_data)
        await retry_star_refunds(user,message.from_user.id);return
    # No awaits between recording a charge and granting the product's durable balance.
    charges.append(charge)
    # Купон тратим только если счёт и правда был со скидкой купона (сумма ниже цены без купона).
    used_coupon=coupon_active(user) and payload in PRODUCTS and payment.total_amount < product_stars(payload)
    if used_coupon:user['coupon']=None
    first_purchase = not user.get("first_purchase_done")
    await grant_product(user, payload, message.chat.id)
    if used_coupon:await message.answer(get_text(user,'coupon_used'))
    if first_purchase:
        await grant_first_purchase_coupon(user, message.chat.id)


async def grant_first_purchase_coupon(user, chat_id):
    user["first_purchase_done"] = True
    user["coupon"] = {"discount": FIRST_BUY_COUPON,
                      "until": (datetime.now() + timedelta(hours=FIRST_BUY_COUPON_HOURS)).isoformat()}
    save_data(user_data)
    await bot.send_message(chat_id, get_text(user, "coupon_granted", n=int(FIRST_BUY_COUPON * 100), hours=FIRST_BUY_COUPON_HOURS))


