def find_user_id_by_username(username):
    """Ищет user_id по сохранённому username (см. remember_username_middleware) — у Bot API нет
    надёжного способа узнать user_id по @username для произвольного пользователя без этого:
    getChat срабатывает, только если бот уже видел этого пользователя, да и то не всегда."""
    target = username.lstrip("@").lower()
    for user_id, record in user_data.items():
        if user_id == "__settings__" or not isinstance(record, dict):
            continue
        if (record.get("username") or "").lower() == target:
            return int(user_id)
    return None


async def _resolve_admin_target(message: types.Message, target: str):
    if target.startswith("@"):
        found = find_user_id_by_username(target)
        if found is not None:
            return found
        # Запасной вариант — иногда срабатывает, если бот уже знает этого пользователя через
        # Telegram напрямую, но полагаться на это нельзя (см. find_user_id_by_username).
        try:
            return (await bot.get_chat(target)).id
        except Exception:
            pass
        await message.answer(
            "❌ Не найден. Такого username нет в базе бота — человек должен хотя бы раз "
            "написать боту (например /start), прежде чем его можно будет найти по @username. "
            "Можно также передать числовой user_id вместо @username."
        )
        return None
    try:
        return int(target)
    except ValueError:
        await message.answer("❌ Неверный ID.")
        return None


@dp.message(Command("reset_all"))
async def reset_all_cmd(message: types.Message):
    """Полный сброс прогресса ВСЕХ пользователей (админ). Требует подтверждения кнопкой —
    необратимо (кроме резервной копии, которую делаем перед сбросом, см. reset_all_confirm)."""
    if message.from_user.id != MAIN_ADMIN_ID:
        await message.answer("⛔ Нет прав.")
        return
    count = len([k for k in user_data if k != "__settings__"])
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="⚠️ Да, сбросить всех", callback_data="reset_all_confirm", style="danger"),
        InlineKeyboardButton(text="Отмена", callback_data="reset_all_cancel"),
    ]])
    await message.answer(f"⚠️ Сбросить прогресс у ВСЕХ ({count}) пользователей? Все начнут с регистрации "
                         f"заново. Перед сбросом будет сохранена резервная копия данных.", reply_markup=kb)


@dp.callback_query(lambda c: c.data in ("reset_all_confirm", "reset_all_cancel"))
async def reset_all_confirm(call: types.CallbackQuery):
    if call.from_user.id != MAIN_ADMIN_ID:
        await call.answer("⛔ Нет прав.", show_alert=True)
        return
    await safe_delete(call.message)
    if call.data == "reset_all_cancel":
        await call.answer("Отменено")
        return
    backup_path = os.path.join(DATA_DIR, f"data.before_reset_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json")
    with open(backup_path, "w", encoding="utf-8") as f:
        json.dump(user_data, f, ensure_ascii=False)
    removed = [k for k in user_data if k != "__settings__"]
    for k in removed:
        del user_data[k]
    save_data(user_data)
    await call.message.answer(f"✅ Прогресс сброшен у {len(removed)} пользователей.\n"
                              f"Резервная копия: {os.path.basename(backup_path)}")
    await call.answer()


