def make_outfit(gender, rnd):
    """Каждый раз разный наряд: 1-3 аксессуара, иногда верхняя одежда, платье или верх+низ, обувь и бельё."""
    pool = CLOTHES_FEMALE if gender == "female" else CLOTHES_MALE
    picked = [("acc", a) for a in rnd.sample(pool["acc"], rnd.randint(1, 3))]
    if rnd.random() < 0.5:
        picked.append(("outer", rnd.choice(pool["outer"])))
    skirt_like = False
    if gender == "female" and rnd.random() < 0.35:
        picked.append(("dress", pool["dress"][0]))
        skirt_like = True
    else:
        picked.append(("top", rnd.choice(pool["top"])))
        bottom = rnd.choice(pool["bottom"])
        skirt_like = bottom[0] in ("skirt", "shorts")
        picked.append(("bottom", bottom))
    legs = pool["legs"] if skirt_like else [x for x in pool["legs"] if x[0] == "socks"]
    if rnd.random() < (0.7 if gender == "female" else 0.8):
        picked.append(("legs", rnd.choice(legs)))
    picked.append(("shoes", rnd.choice(pool["shoes"])))
    if gender == "female":
        picked += [("bra", pool["bra"][0]), ("panties", pool["panties"][0])]
    else:
        picked.append(("boxers", pool["boxers"][0]))
    return [{"id": f"{cat}-{item[0]}", "cat": cat, "ru": item[1], "en": item[2], "emoji": item[3]} for cat, item in picked]


def cloth_removable(items, item):
    blockers = CLOTH_BLOCKERS.get(item["cat"], set())
    return not any(other["cat"] in blockers or other["id"] in blockers for other in items if other is not item)


def cloth_names(items, lang="ru"):
    return ", ".join(i[lang] for i in items) or ("ничего" if lang == "ru" else "nothing")


def play_strip_allowed(user):
    """Раздевание -- тот же доступ, что у горячих сцен (/hot): возраст подтверждён, соглашение принято, не болен."""
    return bool(user.get("verified") and user.get("agreement_accepted") and not user.get("illness"))


def play_strip_subscribed(user):
    """Сама игра на раздевание -- бесплатно, но только с SUPER PRO / ELITE."""
    return get_subscription_level(user) in ("super_pro", "elite")


def play_self_gender(user):
    """Одежда пользователя -- по полу, который он указал при старте бота."""
    return "female" if user.get("user_gender") == "female" else "male"


# Кастомизация перед игрой: по одной вещи в каждом из 5 слотов, для игрока ("mine") и персонажа ("her").
# Выбор хранится в профиле (user["strip_outfit"]); без выбора наряд случайный, как раньше.
STRIP_SLOTS = ("head", "top", "bottom", "shoes", "accessory")
STRIP_HEADWEAR = ("hat", "cap", "beret", "headband", "beanie")


def strip_slot_options(gender):
    pool = CLOTHES_FEMALE if gender == "female" else CLOTHES_MALE
    options = {"head": [("acc", i) for i in pool["acc"] if i[0] in STRIP_HEADWEAR],
               "accessory": [("acc", i) for i in pool["acc"] if i[0] not in STRIP_HEADWEAR]}
    for slot in ("top", "bottom", "shoes"):
        options[slot] = [(slot, i) for i in pool[slot]]
    return options


def outfit_from_choice(gender, choice):
    """{слот: id вещи} -> список вещей игры; None, если выбор неполный или содержит чужие id."""
    if not isinstance(choice, dict):
        return None
    options = strip_slot_options(gender)
    items = []
    for slot in STRIP_SLOTS:
        match = next(((cat, i) for cat, i in options[slot] if i[0] == choice.get(slot)), None)
        if not match:
            return None
        cat, i = match
        items.append({"id": f"{cat}-{i[0]}", "cat": cat, "ru": i[1], "en": i[2], "emoji": i[3]})
    return items


def serialize_strip_outfit(user, lang):
    def side(gender):
        return {slot: [{"id": i[0], "name": i[1] if lang == "ru" else i[2], "emoji": i[3]} for _, i in opts]
                for slot, opts in strip_slot_options(gender).items()}
    return {"slots": list(STRIP_SLOTS), "saved": user.get("strip_outfit") or {},
            "options": {"mine": side(play_self_gender(user)), "her": side(user.get("gender") or "female")}}


def retire_blackjack(user):
    """Refund unresolved legacy stakes exactly once and remove retired game state."""
    changed = False
    for key, field in (('game','type'),('play','mode')):
        old = user.get(key)
        if isinstance(old,dict) and old.get(field) == 'bj':
            active = key == 'game' or old.get('phase') == 'turn'
            if active:
                user['bucks'] = user.get('bucks',0)+max(0,int(old.get('bet',0)))
            user[key] = None
            changed = True
    return changed


def online_store():
    return user_data.setdefault('__settings__',{}).setdefault('online_rooms',{})


def online_adult_allowed(user):
    return bool(user.get('verified') and user.get('agreement_accepted') and get_subscription_level(user) in ('super_pro','elite'))


async def expire_online_rooms():
    """Settle deadlines even when both clients closed the app."""
    while True:
        before=None
        wallets={}
        store=None
        try:
            sync_data()
            store=online_store()
            before=copy.deepcopy(store)
            wallets={uid:user_data[uid].get('bucks',0) for room in store.values() for uid in room['players'] if uid!='bot' and uid in user_data}
            online_games.expire(store,user_data,time.time())
            if store!=before:
                save_data(user_data)
        except Exception as exc:
            if before is not None and store is not None:
                store.clear();store.update(before)
                for uid,bucks in wallets.items():user_data[uid]['bucks']=bucks
            logging.error('Online deadline settlement: %s',type(exc).__name__)
        await asyncio.sleep(3)


async def online_page_handler(request):
    if not _BOT_USERNAME['v']:
        try:
            await asyncio.wait_for(bot_username(), timeout=5)
        except asyncio.TimeoutError:
            pass
    return page_response(request, online_ui.PAGE_HTML)


ONLINE_SKINS={
 'anime_f_short':('Аниме · короткие волосы','player_avatar_anime_female_short'),
 'anime_f_long':('Аниме · длинные волосы','player_avatar_anime_female_long'),
 'anime_m_crop':('Аниме · мужской образ','player_avatar_anime_male_crop'),
 'anime_m_medium':('Аниме · средние волосы','player_avatar_anime_male_medium'),
 'real_f_short':('Реализм · короткие волосы','player_avatar_realism_female_short'),
 'real_m_crop':('Реализм · мужской образ','player_avatar_realism_male_crop'),
}


async def api_online_handler(request):
    uid, user, body, err = await _play_request(request)
    if err:
        return err
    uid = str(uid)
    store = online_store()
    original = copy.deepcopy(store)
    affected = {uid} | {p for room in store.values() for p in room['players'] if p != 'bot'}
    wallets = {p: {k:user_data[p].get(k) for k in ('bucks','online_room','online_invite','online_skin')} for p in affected if p in user_data}
    failure = None
    preview = None
    try:
        online_games.expire(store,user_data,time.time())
        action = body.get('action','state')
        room = online_games.current(store,user_data,uid)
        if action == 'state' and room and room['status']=='waiting' and time.time()-room.get('seen',0)>=5:
            room['seen']=time.time()
        if action in ('start','join') and body.get('skin') is not None:
            skin=body.get('skin')
            if skin not in ONLINE_SKINS:raise online_games.GameError('invalid_request')
            if room and room['status'] in ('playing','waiting'):raise online_games.GameError('already_playing')
            user['online_skin']=skin
        if action == 'start':
            game = body.get('game')
            if game == 'rps18' and (not online_adult_allowed(user) or body.get('adult') is not True):
                raise online_games.GameError('adult_required')
            # A queued player whose entitlement expired cannot be matched in 18+ mode.
            for waiting in list(store.values()):
                if waiting['status']=='waiting' and waiting['game']=='rps18' and not online_adult_allowed(user_data[waiting['players'][0]]):
                    online_games.finish(waiting,None,user_data,'cancelled')
            online_games.start(store,user_data,uid,game,body.get('bet',0),body.get('kind','random'))
        elif action in ('preview','join'):
            code = str(body.get('code','')).strip().upper()
            candidate = store.get(code)
            if not re.fullmatch('[0-9A-F]{8}',code) or not candidate or candidate['status']!='waiting':
                raise online_games.GameError('room_unavailable')
            if action == 'preview':
                preview = {k:candidate[k] for k in ('game','bet','id')}
            else:
                if type(body.get('bet')) is not int or body['bet'] != candidate['bet']:
                    raise online_games.GameError('invalid_request')
                if candidate['game']=='rps18' and (body.get('adult') is not True or not online_adult_allowed(user) or not online_adult_allowed(user_data[candidate['players'][0]])):
                    raise online_games.GameError('adult_required')
                online_games.join(store,user_data,uid,code)
                user.pop('online_invite',None)
        elif action in ('move','leave'):
            if not room or body.get('room') != room['id']:
                raise online_games.GameError('not_member')
            if action == 'leave':
                online_games.leave(room,user_data,uid)
            else:
                move = body.get('move')
                if not isinstance(move,dict):
                    raise online_games.GameError('invalid_request')
                online_games.move(room,user_data,uid,body.get('seq'),move)
                online_games.bot_turn(room,user_data,time.time())
        elif action != 'state':
            raise online_games.GameError('invalid_request')
    except online_games.GameError as exc:
        failure = str(exc)
    except Exception as exc:
        logging.error('Online game error: %s',type(exc).__name__)
        failure = 'save_failed'
        store.clear();store.update(original)
        for p, fields in wallets.items():
            for key,value in fields.items():
                if value is None:user_data[p].pop(key,None)
                else:user_data[p][key]=value
    try:
        if original != store or any(user_data[p].get(k)!=value for p,fields in wallets.items() for k,value in fields.items()):
            save_data(user_data)
    except Exception:
        store.clear();store.update(original)
        for p,fields in wallets.items():
            for key,value in fields.items():
                if value is None:user_data[p].pop(key,None)
                else:user_data[p][key]=value
        failure='save_failed'
    current = online_games.current(store,user_data,uid)
    room_view=online_games.view(current,uid)
    if room_view and current:
        room_view['skins']=[{'image':'/assets/'+ONLINE_SKINS.get((user_data.get(p) or {}).get('online_skin'),ONLINE_SKINS['anime_m_crop'])[1]+'.webp','name':('Компьютер' if p=='bot' else 'Твой персонаж' if p==uid else 'Персонаж соперника')} for p in current['players']]
    return web.json_response({'ok':failure is None,'error':failure,'preview':preview,'state':{
        'lang':user.get('lang','ru'),'bucks':user.get('bucks',0),'bets':list(online_games.BETS),
        'adult_allowed':online_adult_allowed(user),'invite':user.get('online_invite'),
        'skin':user.get('online_skin','anime_m_crop'),'skins':[{'key':key,'name':value[0],'image':'/assets/'+value[1]+'.webp'} for key,value in ONLINE_SKINS.items()],
        'bot_username':_BOT_USERNAME['v'],'server_time':time.time(),
        'room':room_view}})


def serialize_play_state(user):
    if retire_blackjack(user):
        save_data(user_data)
    lang = "ru" if user.get("lang", "ru") == "ru" else "en"
    play = user.get("play")
    game = None
    if play and play.get("mode") in PLAY_TALK_MODES:
        game = serialize_talk(user, play)
        play = None
    if play:
        pick = play.get("phase")
        def items(side, picker):
            lst = play[side]
            return [{"id": i["id"], "name": i[lang], "emoji": i["emoji"],
                     "removable": pick == picker and cloth_removable(lst, i)} for i in lst]
        game = {"mode": play["mode"], "phase": play["phase"], "me": play.get("me", 0), "ai": play.get("ai", 0),
                "last": play.get("last"), "line": play.get("line"), "result": play.get("result"), "took": play.get("took"),
                "busy": bool(play.get("busy")), "pending": play.get("pending"),
                "her": items("her", "pick_her") if play["mode"] == "strip" else [],
                "mine": items("mine", "pick_me") if play["mode"] == "strip" else [],
                "her_removed": len(play.get("her_removed", [])), "mine_removed": len(play.get("mine_removed", []))}
    ui = {k: gt(user, k) for k in GAME_TEXTS["ru"] if k.startswith("play_") and isinstance(GAME_TEXTS["ru"][k], str)}
    return {"lang": user.get("lang","ru"), "bucks": user.get("bucks", 0), "price": PLAY_RPS_PRICE, "wins": PLAY_RPS_WINS,
            "movie_price": GAME_OFFERS["movie"]["price"], "tod_labels": {"truth": gt(user, "tod_truth"), "dare": gt(user, "tod_dare")},
            "strip_allowed": play_strip_allowed(user), "strip_subscribed": play_strip_subscribed(user),
            "outfit": serialize_strip_outfit(user, lang) if play_strip_allowed(user) else None,
            "char_gender": user.get("gender") or "female",
            "rps_names": gt(user, "rps_names"), "game": game, "ui": ui}


async def play_ai(user_id, user, instruction, fallback_key):
    line = await game_ai_line(user_id, user, instruction)
    return line or random.choice(gt(user, fallback_key))


async def play_finish(user_id, user, won):
    play = user["play"]
    play["phase"] = "over"
    play["result"] = "win" if won else "lose"
    xp = (PLAY_STRIP_XP if play["mode"] == "strip" else PLAY_RPS_XP) if won else 0
    save_data(user_data)
    if xp:
        await grant_gift_xp(user_id, user, xp)


async def _play_request(request):
    init_data = request.headers.get("X-Telegram-Init-Data", "")
    user_id, user, error = resolve_webapp_user(init_data)
    if error:
        return None, None, None, web.json_response(error, status=401 if error["error"] == "auth" else 200)
    try:
        body = await request.json()
    except Exception:
        body = {}
    return user_id, user, body if isinstance(body, dict) else {}, None


def _play_reply(user, ok=True, error=None):
    return web.json_response({"ok": ok, "error": error, "state": serialize_play_state(user)})


async def api_play_state_handler(request):
    user_id, user, body, err = await _play_request(request)
    if err:
        return err
    play_unstick(user)
    return _play_reply(user)


async def api_play_start_handler(request):
    user_id, user, body, err = await _play_request(request)
    if err:
        return err
    mode = body.get("mode")
    if mode not in ("rps", "strip") + PLAY_TALK_MODES:
        return _play_reply(user, False, "Bad request")
    if mode in PLAY_TALK_MODES:
        user["game"] = None
        error = games_gate_error(user)
        if error:
            return _play_reply(user, False, error)
        user["play"] = play_talk_start(user, mode)
        save_data(user_data)
        return _play_reply(user)
    if user.get("game"):
        user["game"] = None  # чатовая партия, если висела, не мешает
    error = games_gate_error(user)
    if error:
        return _play_reply(user, False, error)
    if mode == "strip":
        if not play_strip_allowed(user):
            return _play_reply(user, False, gt(user, "play_strip_locked"))
        if not play_strip_subscribed(user):
            return _play_reply(user, False, gt(user, "play_need_super"))
    elif not spend_bucks(user, PLAY_RPS_PRICE):
        return _play_reply(user, False, get_text(user, "not_enough_bucks", n=PLAY_RPS_PRICE - user.get("bucks", 0)))
    rnd = random.Random()
    char_gender = user.get("gender") or "female"
    self_gender = play_self_gender(user)
    saved = user.get("strip_outfit") or {}
    her_outfit = (outfit_from_choice(char_gender, saved.get("her")) or make_outfit(char_gender, rnd)) if mode == "strip" else []
    my_outfit = (outfit_from_choice(self_gender, saved.get("mine")) or make_outfit(self_gender, rnd)) if mode == "strip" else []
    user["play"] = {"mode": mode, "phase": "move", "me": 0, "ai": 0, "last": None, "line": None, "result": None,
                    "her": her_outfit, "mine": my_outfit,
                    "her_removed": [], "mine_removed": [], "busy": False}
    save_data(user_data)
    return _play_reply(user)


# Реплика персонажа в мини-играх пишется В ФОНЕ: результат раунда приходит сразу (по фидбэку игра «зависала»
# на проигрыше, пока ИИ думал), а клиент показывает «персонаж печатает…» и опрашивает /api/play/state, пока busy.
PLAY_BUSY_STALE_SECONDS = 90

# Как персонаж ведёт себя на раздевании -- под выбранный стиль (дерзкая -- «блин, ну придётся…», страстная --
# «ух ты, шалунишка…», стеснительная -- краснеет и медлит).
PLAY_STRIP_STYLE = {
    "warm": "тепло, нежно и с лёгким смущением, улыбаешься",
    "daring": "дерзко и с вызовом — вроде «блин, ну ладно, придётся снимать для тебя…», подначиваешь и не сдаёшься",
    "shy": "очень стеснительно: краснеешь, медлишь, прикрываешься, говоришь тихо и сбивчиво, но всё-таки делаешь",
    "passionate": "страстно и игриво — вроде «ух ты, шалунишка, вот что выбрал(а)? ну давай, любуйся мной», с огоньком",
    "magnetic": "уверенно и притягательно: медленно, держишь взгляд, будто это ты управляешь ситуацией",
    "rude": "грубовато и насмешливо, с подколками, но так, что это заводит",
    "seduction": "соблазнительно и медленно, дразнишь каждым движением и словом",
}


# А когда раунд выиграл персонаж и он сам выбирает, что снять с собеседника:
PLAY_TAKE_STYLE = {
    "warm": "мягко и игриво, с тёплой улыбкой",
    "daring": "дерзко, с вызовом и подколкой — командуешь и смотришь, не струсит ли",
    "shy": "смущённо: краснеешь от собственной смелости, но выбор всё-таки делаешь",
    "passionate": "страстно, с огоньком и предвкушением — тебе явно не терпится",
    "magnetic": "спокойно и властно, уверенным тоном, будто всё идёт по твоему плану",
    "rude": "грубовато и нагло, с насмешкой",
    "seduction": "соблазнительно и медленно, растягивая удовольствие",
}


def play_style_hint(user, taking=False):
    table = PLAY_TAKE_STYLE if taking else PLAY_STRIP_STYLE
    return table.get(user.get("style"), table["warm"])


def play_round_facts(user, play):
    """Что реально выпало в ЭТОМ раунде -- чтобы персонаж не путал ходы и не придумывал новые."""
    last = play.get("last")
    if not last:
        return ""
    if play.get('mode')=='strip':return 'Раунд уже сыгран. Продолжай только текущий момент с одеждой и реакцией персонажа; не пересказывай игровые ходы. '
    names = GAME_TEXTS["ru"]["rps_names"]
    return (f"В этом раунде ты показал(а) «{names[last['theirs']]}», а собеседник — «{names[last['mine']]}». "
            "Раунд уже сыгран: не придумывай и не описывай других ходов, не выбрасывай новую фигуру и не говори о "
            "прошлых раундах как о текущем. ")


def play_run_bg(user_id, user, play, job):
    """Запускает реплику персонажа в фоне. job() -- корутина; пока она идёт, play["busy"] блокирует ходы."""
    token = f"{random.getrandbits(32):08x}"
    play["busy"] = True
    play["busy_token"] = token
    play["busy_at"] = datetime.now().isoformat()

    async def runner():
        try:
            await job()
        except Exception as e:
            logging.warning(f"play bg line: {e}")
        finally:
            if play.get("busy_token") == token:
                if play.get("pending") == "take":
                    play_take_fallback(user, play)
                play["busy"] = False
                play["pending"] = None
            save_data(user_data)

    asyncio.create_task(runner())


def play_unstick(user):
    """Если фоновая реплика так и не пришла (рестарт бота, зависший запрос) -- снимаем блок."""
    play = user.get("play")
    if not play or not play.get("busy"):
        return
    try:
        age = (datetime.now() - datetime.fromisoformat(play.get("busy_at"))).total_seconds()
    except (ValueError, TypeError):
        age = PLAY_BUSY_STALE_SECONDS + 1
    if age > PLAY_BUSY_STALE_SECONDS:
        if play.get("pending") == "take":
            play_take_fallback(user, play)
        play["busy"] = False
        play["pending"] = None
        play["busy_token"] = None
        save_data(user_data)


async def api_play_outfit_handler(request):
    """Сохраняет выбор одежды в профиле. Тот же доступ, что у самой игры: 18+, соглашение, не болен."""
    user_id, user, body, err = await _play_request(request)
    if err:
        return err
    if not play_strip_allowed(user):
        return _play_reply(user, False, gt(user, "play_strip_locked"))
    mine, her = body.get("mine"), body.get("her")
    if outfit_from_choice(play_self_gender(user), mine) is None or outfit_from_choice(user.get("gender") or "female", her) is None:
        return _play_reply(user, False, gt(user, "play_outfit_invalid"))
    user["strip_outfit"] = {"mine": {s: mine[s] for s in STRIP_SLOTS}, "her": {s: her[s] for s in STRIP_SLOTS}}
    save_data(user_data)
    return _play_reply(user)


async def api_play_move_handler(request):
    user_id, user, body, err = await _play_request(request)
    if err:
        return err
    play = user.get("play")
    choice = body.get("choice")
    if play and play.get("phase") == "pick_me":
        play["phase"] = "move"  # партии со старым ходом "выбери сам" доигрываются по новым правилам
    if not play or play.get("phase") != "move" or choice not in RPS_KEYS or play.get("busy"):
        return _play_reply(user, False, None)
    theirs = random.choice(RPS_KEYS)
    beats = {"rock": "scissors", "scissors": "paper", "paper": "rock"}
    outcome = "draw" if choice == theirs else ("win" if beats[choice] == theirs else "lose")
    play["last"] = {"mine": choice, "theirs": theirs, "outcome": outcome}
    play["line"] = None
    play["took"] = None
    if play["mode"] == "rps":
        if outcome == "win":
            play["me"] += 1
        elif outcome == "lose":
            play["ai"] += 1
        if play["me"] >= PLAY_RPS_WINS or play["ai"] >= PLAY_RPS_WINS:
            won = play["me"] >= PLAY_RPS_WINS
            await play_finish(user_id, user, won)
            facts = "собеседник обыграл тебя" if won else "ты обыграл(а) собеседника"
            instr = (f"Вы играли в камень-ножницы-бумагу до {PLAY_RPS_WINS} побед, итоговый счёт {play['me']}:{play['ai']} "
                     f"в пользу {'собеседника' if won else 'тебя'}: {facts}. " + play_round_facts(user, play) +
                     "Отреагируй в образе: подколи, порадуйся или предложи реванш.")

            async def job():
                line = await game_ai_line(user_id, user, instr, tail=play_tail(play))
                play_log(play, line)
                play["line"] = line or random.choice(gt(user, "play_fallback_rps"))
            play_run_bg(user_id, user, play, job)
    elif outcome == "win":
        play["phase"] = "pick_her"
    elif outcome == "lose":
        play["pending"] = "take"

        async def job():
            await play_character_takes(user_id, user, play)
            if not play["mine"]:
                await play_finish(user_id, user, False)
        play_run_bg(user_id, user, play, job)
    save_data(user_data)
    return _play_reply(user)


def play_take_options(play):
    return [i for i in play["mine"] if cloth_removable(play["mine"], i)]


def play_apply_take(user, play, item, text):
    lang = "ru" if user.get("lang", "ru") == "ru" else "en"
    if not text:
        text = random.choice(gt(user, "play_fallback_take")).format(item=item[lang] if lang == "ru" else item[lang].lower())
    play["mine"].remove(item)
    play["mine_removed"].append(item)
    play["took"] = f"{item['emoji']} {item[lang]}"
    play["line"] = text
    play["pending"] = None
    play_log(play, text)


def play_take_fallback(user, play):
    """ИИ не ответил -- персонаж всё равно забирает вещь (заготовкой), иначе партия застрянет."""
    options = play_take_options(play)
    if options:
        play_apply_take(user, play, random.choice(options), None)
        if not play["mine"]:
            play["phase"] = "over"
            play["result"] = "lose"
    play["pending"] = None


async def play_character_takes(user_id, user, play):
    """Персонаж выиграл раунд -- сам выбирает, что снять с собеседника, и говорит это в своём стиле."""
    options = play_take_options(play)
    if not options:
        play["pending"] = None
        return
    numbered = "; ".join(f"{n}) {i['ru']}" for n, i in enumerate(options, 1))
    rest = cloth_names(play["mine"])
    last = len(play["mine"]) == 1
    she = play_self_gender(user) == "female"
    instr = ("Игра «камень-ножницы-бумага на раздевание», ставка — только одежда. " + play_round_facts(user, play) +
             f"Ты выиграл(а) этот раунд и сам(а) решаешь, что {'собеседница' if she else 'собеседник'} снимет. "
             f"Сейчас на {'ней' if she else 'нём'}: {rest}. Снять можно: {numbered}. Выбери то, что тебе самой/самому "
             "интереснее увидеть снятым. Начни ответ строго с номера в квадратных скобках, например [2], а дальше — "
             f"с ухмылкой, заигрывая, скажи, что выбираешь и почему, и подразни. Манера: {play_style_hint(user, taking=True)}. "
             + (f"Это {'её' if she else 'его'} последняя вещь — после неё {'она полностью раздета' if she else 'он полностью раздет'} "
                "и ты выигрываешь игру." if last else ""))
    text = await game_ai_line(user_id, user, instr, tail=play_tail(play))
    if play.get("pending") != "take":
        return  # уже отработала страховка
    item = None
    if text:
        m = re.match(r"\s*\[(\d+)\]\s*", text)
        if m and 1 <= int(m.group(1)) <= len(options):
            item = options[int(m.group(1)) - 1]
        text = re.sub(r"\[\d+\]\s*", "", text, count=1).strip() or None
    if item is None:
        item = random.choice(options)
        if text and item["ru"].lower() not in text.lower():
            text = None  # модель не назвала номер, а в реплике другая вещь -- лучше заготовка, чем путаница
    play_apply_take(user, play, item, text)


def play_tail(play):
    """Последние реплики персонажа в этой партии -- чтобы он помнил, что уже говорил, и не повторялся."""
    return [{"role": "assistant", "content": t} for t in play.get("log", [])[-4:]]


def play_log(play, text):
    if text:
        play.setdefault("log", []).append(text)
        play["log"] = play["log"][-6:]


async def api_play_remove_handler(request):
    user_id, user, body, err = await _play_request(request)
    if err:
        return err
    play = user.get("play")
    if not play or play.get("mode") != "strip" or play.get("phase") != "pick_her" or play.get("busy"):
        return _play_reply(user, False, None)
    item = next((i for i in play["her"] if i["id"] == body.get("item")), None)
    if not item or not cloth_removable(play["her"], item):
        return _play_reply(user, False, gt(user, "play_cant_remove"))
    play["her"].remove(item)
    play["her_removed"].append(item)
    play["phase"] = "move"
    play["line"] = None
    last = not play["her"]
    if last:
        await play_finish(user_id, user, True)
    rest = cloth_names(play["her"])
    she_user = play_self_gender(user) == "female"
    instr = ("Игра «камень-ножницы-бумага на раздевание», ставка — только одежда. " + play_round_facts(user, play) +
             f"Ты проиграл(а) этот раунд, и {'собеседница выбрала' if she_user else 'собеседник выбрал'}, что тебе снять: "
             f"«{item['ru']}». Сначала отреагируй именно на этот выбор (почему именно это?), потом опиши от первого лица, "
             f"как ты это снимаешь. Манера: {play_style_hint(user)}. "
             + ("Это была последняя вещь — теперь на тебе ничего нет, ты проиграл(а) всю игру: отреагируй ярко."
                if last else f"На тебе ещё: {rest}."))

    async def job():
        line = await game_ai_line(user_id, user, instr, tail=play_tail(play))
        play_log(play, line)
        play["line"] = line or random.choice(gt(user, "play_fallback_her"))
    play_run_bg(user_id, user, play, job)
    save_data(user_data)
    return _play_reply(user)


# ---------- Разговорные игры в мини-приложении: Города, Правда или действие, Кино ----------
# Те же правила, что были в чате, только реплики персонажа и ходы игрока живут в мини-чате партии (play["talk"]),
# а ответ ИИ пишется в фоне (play_run_bg) -- страница показывает «печатает…».
PLAY_TALK_MODES = ("cities", "tod", "movie")
PLAY_TALK_SHOWN = 40


def talk_add(play, who, text):
    if text:
        play.setdefault("talk", []).append({"who": who, "text": text})
        play["talk"] = play["talk"][-PLAY_TALK_SHOWN:]


def play_talk_start(user, mode):
    play = {"mode": mode, "talk": [], "busy": False, "result": None, "log": []}
    if mode == "cities":
        play.update(phase="input", c_used=[], c_last=None, moves=0, started=datetime.now().isoformat())
        talk_add(play, "sys", gt(user, "cities_start"))
    elif mode == "tod":
        play.update(phase="pick", round=0)
        talk_add(play, "sys", gt(user, "tod_start", rounds=TOD_ROUNDS))
    else:
        play.update(phase="genre", beat=0, genre=None)
        talk_add(play, "sys", gt(user, "movie_pick", price=GAME_OFFERS["movie"]["price"], bucks=user.get("bucks", 0)))
    return play


async def play_talk_finish(user_id, user, play, result, xp=0, text_key=None, **kw):
    """Конец разговорной партии: итог в мини-чат и XP (xp подставляется и в текст итога)."""
    play["phase"] = "over"
    play["result"] = result
    if text_key:
        talk_add(play, "sys", gt(user, text_key, xp=xp, **kw))
    save_data(user_data)
    if xp:
        await grant_gift_xp(user_id, user, xp)


def serialize_talk(user, play):
    letter = city_last_letter(play["c_last"]).upper() if play.get("mode") == "cities" and play.get("c_last") else None
    return {"mode": play["mode"], "phase": play["phase"], "talk": play.get("talk", []), "busy": bool(play.get("busy")),
            "result": play.get("result"), "letter": letter, "round": play.get("round", 0) + 1, "rounds": TOD_ROUNDS,
            "beat": play.get("beat", 0), "beats": MOVIE_BEATS, "genres": gt(user, "movie_genres"),
            "reacts": gt(user, "movie_react"), "price": GAME_OFFERS["movie"]["price"]}


async def play_cities_text(user_id, user, play, text):
    norm = city_norm(text)
    city = CITY_BY_NORM.get(norm)
    need = city_last_letter(play["c_last"]) if play.get("c_last") else None
    if not city:
        return gt(user, "cities_unknown", letter=need.upper() if need else "—")
    if need and city_first_letter(city) != need:
        return gt(user, "cities_wrong_letter", letter=need.upper())
    if city in play["c_used"]:
        return gt(user, "cities_used")
    talk_add(play, "me", city)
    play["moves"] = play.get("moves", 0) + 1
    try:
        too_long = (datetime.now() - datetime.fromisoformat(play["started"])).total_seconds() > CITIES_MAX_MINUTES * 60
    except (KeyError, ValueError, TypeError):
        too_long = True
    if play["moves"] > CITIES_MAX_MOVES or too_long:
        await play_talk_finish(user_id, user, play, "draw", text_key="cities_timeup")
        return None
    play["c_used"].append(city)
    letter = city_last_letter(city)
    options = [c for c in CITY_LIST if c not in play["c_used"] and city_first_letter(c) == letter]
    if not options:
        talk_add(play, "ai", gt(user, "cities_stuck", letter=letter.upper()))
        await play_talk_finish(user_id, user, play, "win", xp=CITIES_XP, text_key="cities_win", prize=CITIES_PRIZE)
        return None
    mine = random.choice(options)
    play["c_used"].append(mine)
    play["c_last"] = mine
    next_letter = city_last_letter(mine)
    instr = (f"Вы играете в города. Собеседник назвал «{city}». Ты называешь город «{mine}» — обязательно назови именно его, "
             f"в конце реплики. Следующий город собеседнику нужен на букву «{next_letter.upper()}». Реагируй в своём стиле: "
             "смейся, подначивай, радуйся.")

    async def job():
        line = await game_ai_line(user_id, user, instr, tail=play_tail(play))
        play_log(play, line)
        talk_add(play, "ai", (line + "\n\n" if line else "") + f"🏙 {mine} — {gt(user, 'cities_your_letter', letter=next_letter.upper())}")
    play_run_bg(user_id, user, play, job)
    return None


async def play_tod_pick(user_id, user, play, kind):
    if play["phase"] != "pick" or kind not in ("truth", "dare"):
        return None
    play["phase"] = "answer"
    play["kind"] = kind
    talk_add(play, "me", gt(user, "tod_truth" if kind == "truth" else "tod_dare"))
    if kind == "truth":
        task, word = "Задай ему один личный, тёплый, чуть смущающий вопрос (правда); не пошлый, не про деньги и не про здоровье.", "правду"
    else:
        task, word = ("Придумай одно безобидное весёлое задание, которое можно выполнить прямо в чате (описать, написать, придумать, "
                      "изобразить словами); без нарушений правил и без пошлости."), "действие"

    async def job():
        line = await game_ai_line(user_id, user, f"Игра «правда или действие». Собеседник выбрал {word}. {task} Только один вопрос или задание.",
                                  tail=play_tail(play))
        line = line or random.choice(gt(user, "tod_fallback_truth" if kind == "truth" else "tod_fallback_dare"))
        play_log(play, line)
        talk_add(play, "ai", line)
        talk_add(play, "sys", gt(user, "tod_answer_hint"))
    play_run_bg(user_id, user, play, job)
    return None


async def play_tod_text(user_id, user, play, text):
    phase = play["phase"]
    if phase == "pick":
        return gt(user, "tod_use_buttons")
    text = text[:400]
    talk_add(play, "me", text)
    if phase == "answer":
        ai_kind = random.choice(["truth", "dare"])
        play["ai_kind"] = ai_kind
        play["phase"] = "ask"

        async def job():
            line = await game_ai_line(user_id, user, f"Игра «правда или действие». Собеседник ответил/выполнил: «{text}». Отреагируй в образе "
                                                      "(смех, удивление, смущение, поддержка), без осуждения.", tail=play_tail(play))
            play_log(play, line)
            talk_add(play, "ai", line)
            talk_add(play, "sys", gt(user, "tod_ai_turn", kind=gt(user, f"tod_kind_{ai_kind}"), what=gt(user, f"tod_what_{ai_kind}")))
        play_run_bg(user_id, user, play, job)
    elif phase == "ask":
        play["phase"] = "pick"
        if play.get("ai_kind") == "truth":
            instr = (f"Игра «правда или действие». Ты выбрала правду, собеседник спросил: «{text}». Ответь честно и по-настоящему в образе, "
                     "от первого лица; если вопрос слишком грубый — мягко уйди от ответа с шуткой.")
        else:
            instr = (f"Игра «правда или действие». Ты выбрала действие, собеседник придумал: «{text}». Выполни это словами в образе "
                     "(опиши, что делаешь); если задание слишком грубое или нарушает правила — отшутись и предложи смягчить.")

        async def job():
            line = await game_ai_line(user_id, user, instr, tail=play_tail(play))
            play_log(play, line)
            talk_add(play, "ai", line)
            play["round"] = play.get("round", 0) + 1
            if play["round"] >= TOD_ROUNDS:
                await play_talk_finish(user_id, user, play, "win", text_key="tod_finished", xp=TOD_XP)
            else:
                talk_add(play, "sys", gt(user, "tod_pick_prompt", n=play["round"] + 1, total=TOD_ROUNDS))
        play_run_bg(user_id, user, play, job)
    return None


async def play_movie_beat(user_id, user, play, reaction):
    play["beat"] = play.get("beat", 0) + 1
    last = play["beat"] >= MOVIE_BEATS
    plot = MOVIE_PLOTS[play["genre"]]
    reaction_text = {"start": "Вы только сели смотреть, фильм начинается", "cry": "собеседник расчувствовался и плачет",
                     "laugh": "собеседник смеётся", "hug": "собеседник прижался к тебе", "comment": "собеседник что-то шепчет про фильм"}[reaction]
    instruction = (f"Вы вдвоём смотрите кино (сцена {play['beat']} из {MOVIE_BEATS}): {plot}. {reaction_text}. "
                   "Коротко опиши, что происходит на экране, и свою живую реакцию (плачешь, смеёшься, пугаешься, прижимаешься)"
                   + (". Это финал фильма — завершай историю тёплой репликой после титров." if last else ". Оставь интригу для следующей сцены."))

    async def job():
        line = await game_ai_line(user_id, user, instruction, tail=play_tail(play))
        play_log(play, line)
        talk_add(play, "ai", line or "…")
        if last:
            await play_talk_finish(user_id, user, play, "win", text_key="movie_done", xp=MOVIE_XP)
    play_run_bg(user_id, user, play, job)


async def api_play_talk_handler(request):
    user_id, user, body, err = await _play_request(request)
    if err:
        return err
    play = user.get("play")
    action, value = body.get("action"), body.get("value")
    if not play or play.get("mode") not in PLAY_TALK_MODES or play.get("phase") == "over":
        return _play_reply(user, False, None)
    if action == "end":
        await play_talk_finish(user_id, user, play, "lose" if play["mode"] == "cities" else "stop",
                               text_key="cities_lose" if play["mode"] == "cities" else None)
        return _play_reply(user)
    if play.get("busy"):
        return _play_reply(user, False, gt(user, "tod_wait"))
    error = None
    if play["mode"] == "cities" and action == "text":
        error = await play_cities_text(user_id, user, play, (value or "").strip()[:60])
    elif play["mode"] == "tod" and action == "pick":
        error = await play_tod_pick(user_id, user, play, value)
    elif play["mode"] == "tod" and action == "text" and (value or "").strip():
        error = await play_tod_text(user_id, user, play, value.strip())
    elif play["mode"] == "movie" and action == "genre" and play["phase"] == "genre" and value in MOVIE_PLOTS:
        if pay_for_game(user, "movie") is None:
            price = GAME_OFFERS["movie"]["price"]
            return _play_reply(user, False, get_text(user, "not_enough_bucks", n=price - user.get("bucks", 0)))
        play["genre"] = value
        play["phase"] = "react"
        talk_add(play, "me", gt(user, "movie_genres")[value])
        await play_movie_beat(user_id, user, play, "start")
    elif play["mode"] == "movie" and action == "react" and play["phase"] == "react" and value in ("cry", "laugh", "hug", "comment"):
        talk_add(play, "me", gt(user, "movie_react")[value])
        await play_movie_beat(user_id, user, play, value)
    else:
        return _play_reply(user, False, None)
    save_data(user_data)
    return _play_reply(user, error is None, error)


async def api_play_quit_handler(request):
    user_id, user, body, err = await _play_request(request)
    if err:
        return err
    user["play"] = None
    save_data(user_data)
    return _play_reply(user)


async def play_page_handler(request):
    return page_response(request, PLAY_PAGE_HTML)


