def at(user, key, **kw):
    lang = user.get("lang", "ru")
    if lang not in APP_TEXTS: lang = "en"
    text = APP_TEXTS[lang].get(key, APP_TEXTS["ru"][key])
    return text.format(**kw) if kw and isinstance(text, str) else text


def app_avatar(user):
    female = (user.get("gender") or "female") == "female"
    if user.get("world") == "anime":
        return "🌸" if female else "⚔️"
    return "👩🏻" if female else "👨🏻"


def app_request_user(init_data):
    """Как resolve_webapp_user, но пускает и без созданного персонажа -- его создают прямо в приложении."""
    parsed = validate_webapp_init_data(init_data)
    if not parsed or not (parsed.get("user") or {}).get("id"):
        return None, None, {"ok": False, "error": "auth", "message": "Invalid Telegram signature"}
    user_id = int(parsed["user"]["id"])
    if STAGING_MODE and user_id not in STAGING_TESTER_IDS:return None,None,{'ok':False,'error':'staging','message':'Тестовая версия доступна только участникам проверки'}
    user = get_user(user_id)
    if (maintenance_mode and user_id != MAIN_ADMIN_ID) or (user_id==MAIN_ADMIN_ID and user.get('maintenance_preview')):
        return None, None, {"ok": False, "error": "maintenance", "message": get_text(user, "maintenance"), "lang":user.get("lang","ru")}
    if not (user["verified"] and user["agreement_accepted"]):
        return None, None, {"ok": False, "error": "not_ready", "message": get_text(user, "webapp_character_not_ready")}
    return user_id, user, None


async def _app_request(request, allow_dead=False):
    user_id, user, error = app_request_user(request.headers.get("X-Telegram-Init-Data", ""))
    if not error and user.get("dead") and not allow_dead:error={"ok":False,"error":"dead","message":get_text(user,"character_died")}
    if error:
        return None, None, None, web.json_response(error, status=401 if error["error"] == "auth" else 200)
    try:
        body = await request.json()
    except Exception:
        body = {}
    return user_id, user, body if isinstance(body, dict) else {}, None


def serialize_onboarding(user):
    lang = user.get("lang") or "ru"
    sub = get_subscription_level(user)
    styles = []
    for key in STYLES:
        tier = None if is_style_unlocked(key, user) else (style_required_tier(key))
        styles.append({"key": key, "label": style_display_label(key, user), "desc": (STYLES[key].get("summary") or (STYLES[key]["description"],STYLES[key]["label_en"],STYLES[key]["label_de"]))[{"ru":0,"en":1,"de":2}.get(lang,1)], "locked": tier})
    return {"can_photo_reference":bool(get_subscription_level(user)),"photos":photo_wallet.balance(user),"avatar_attempts":photo_wallet.balance(user)+user.get("portrait_credits",0),"templates":[],"avatar_presets":[],"creation_presets":{g:character_options.creation_presets(lang,g) for g in ("male","female")},"appearance_fields_by_gender":{g:[f for f in character_options.choices(lang,g) if f["key"]!="accessory"] for g in ("male","female")},"races":profile_options.choices(profile_options.RACES,lang),"portrait_enabled":False,"appearance_fields":[f for f in character_options.choices(lang,user.get("gender")) if f["key"]!="accessory"],"appearance_defaults":{k:v for k,v in character_options.DEFAULT.items() if k in character_options.VISUAL_KEYS},"worlds": [{"key": "realism", "label": get_text(user, "realism"), "desc": at(user, "ob_realism")},
                       {"key": "anime", "label": get_text(user, "anime"), "desc": at(user, "ob_anime")}],
            "genders": [{"key": "female", "label": at(user, "ob_female")}, {"key": "male", "label": at(user, "ob_male")}],
            "default_gender": "female" if user.get("user_gender") != "female" else "male",
            "styles": styles,
            "scenes": [{"key": "phone", "label": {"ru":"Переписка","de":"Nachrichten"}.get(lang,"Messages"), "desc": {"ru":"Без описаний действий","de":"Ohne Handlungsbeschreibungen"}.get(lang,"Without action descriptions")},
                       {"key": "live", "label": {"ru":"Ролеплей","de":"Rollenspiel"}.get(lang,"Roleplay"), "desc": {"ru":"С описаниями действий","de":"Mit Handlungsbeschreibungen"}.get(lang,"With action descriptions")}],
            "can_custom": sub in ("super_pro","elite"), "custom_min": CUSTOM_CHARACTER_MIN_LEN, "name_max": CHAR_NAME_MAX,
            "looks": [{"key": k, "world": v["world"], "gender": v["gender"], "img": f"/assets/avatar_{k}.jpg",
                       "label": v["label_ru"] if lang == "ru" else v["label_en"]} for k, v in LOOKS.items()],
            "lang": lang}


def app_unstick(user):
    pending = user.get("app_pending")
    if not pending:
        return
    try:
        age = (datetime.now() - datetime.fromisoformat(pending)).total_seconds()
    except (ValueError, TypeError):
        age = APP_PENDING_STALE_SECONDS + 1
    if age > (360 if user.get('photo_pending') else APP_PENDING_STALE_SECONDS):
        photo_wallet.finish(user,'chat',refund=True)
        if user.get('photo_reserved'):
            user['energy'] = min(ENERGY_MAX,user.get('energy',0)+user.pop('photo_reserved'))
        user.pop('photo_pending', None)
        user["app_pending"] = None
        save_data(user_data)


