async def api_work_hit_handler(request):
    """Одно засчитанное попадание в одной из мгновенных игр (см. register_work_hit) — сразу
    платит баксы, без таймера и без сессии. game передаётся телом запроса ({"game": "clicker"|
    "catch"|"courier"})."""
    init_data = request.headers.get("X-Telegram-Init-Data", "")
    user_id, user, error = resolve_workapp_user(init_data,request)
    if error:
        return web.json_response(error, status=401 if error["error"] == "auth" else 200)
    try:
        body = await request.json()
    except Exception:
        body = {}
    game = body.get("game") if isinstance(body, dict) else None
    if not work_is_open(game, user):return work_closed_reply(user)
    if game=='courier' and courier_v2(user):return web.json_response({'ok':False,'code':'work_version_changed','error':'Используй новый маршрут курьера.','state':serialize_work_state(user)})
    tip = bool(body.get("tip")) if isinstance(body, dict) else False
    hit_id=body.get('hit_id') if isinstance(body,dict) else None
    if hit_id is not None and (not isinstance(hit_id,str) or not re.fullmatch(r'[a-z0-9-]{8,64}',hit_id)):
        return web.json_response({'ok':False,'error':'bad_request'})
    ledger=user.get('work_paid_deliveries') or {}
    if game=='courier' and hit_id and hit_id in ledger:
        return web.json_response({'ok':True,'awarded':ledger[hit_id],'tip':0,'state':serialize_work_state(user)})
    awarded = register_work_hit(user, game, tip=tip)
    if awarded is None:
        return web.json_response({"ok": False, "error": "bad_game", "state": serialize_work_state(user)})
    if game=='courier' and hit_id and awarded:
        ledger[hit_id]=awarded
        user['work_paid_deliveries']=dict(list(ledger.items())[-64:])
        save_data(user_data)
    return web.json_response({"ok": True, "awarded": awarded, "tip": user.get("work_last_tip", 0) if awarded else 0,
                              "state": serialize_work_state(user)})


async def api_work_powerup_handler(request):
    """Бонус из заказа "x2 деньги" (подобранная 💰): включает удвоение выплат за хиты на
    WORK_DOUBLE_SECONDS. Сервер не видит, поймал ли игрок бонус на самом деле, поэтому просто не
    выдаёт его чаще, чем раз в WORK_DOUBLE_COOLDOWN_SECONDS."""
    init_data = request.headers.get("X-Telegram-Init-Data", "")
    user_id, user, error = resolve_workapp_user(init_data,request)
    if error:
        return web.json_response(error, status=401 if error["error"] == "auth" else 200)
    if not work_is_open('catch', user):return work_closed_reply(user)
    now = datetime.now()
    ready_raw = user.get("work_double_next_at")
    granted = False
    if not ready_raw or now.isoformat() >= ready_raw:
        user["work_double_until"] = (now + timedelta(seconds=WORK_DOUBLE_SECONDS)).isoformat()
        user["work_double_next_at"] = (now + timedelta(seconds=WORK_DOUBLE_COOLDOWN_SECONDS)).isoformat()
        save_data(user_data)
        granted = True
    return web.json_response({"ok": True, "granted": granted, "seconds": WORK_DOUBLE_SECONDS,
                              "state": serialize_work_state(user)})


async def api_work_penalty_handler(request):
    """Денежный штраф за провал в catch/courier/clicker (см. register_work_failure) — без
    таймера, может сработать сразу после обычного хита. game передаётся телом запроса, тем же
    набором значений, что и у /api/work/hit."""
    init_data = request.headers.get("X-Telegram-Init-Data", "")
    user_id, user, error = resolve_workapp_user(init_data,request)
    if error:
        return web.json_response(error, status=401 if error["error"] == "auth" else 200)
    try:
        body = await request.json()
    except Exception:
        body = {}
    game = body.get("game") if isinstance(body, dict) else None
    if game=='courier' and courier_v2(user):return web.json_response({'ok':False,'code':'work_version_changed','error':'Штрафы нового курьера проверяет сервер.','state':serialize_work_state(user)})
    penalty = register_work_failure(user, game)
    if penalty is None:
        return web.json_response({"ok": False, "error": "bad_game", "state": serialize_work_state(user)})
    return web.json_response({"ok": True, "penalty": penalty, "state": serialize_work_state(user)})


