def award_referral(user):
    """One durable reward after a new invitee completes registration."""
    if not user.get("referral_pending") or not user.get("personality_ready"):
        return False
    inviter = user_data.get(str(user.get("referred_by")))
    if not isinstance(inviter, dict) or not inviter.get("personality_ready"):
        return False
    old_count = inviter.get("referral_count", 0)
    inviter["referral_earned_bucks"] = inviter.get("referral_earned_bucks", old_count * 300) + REFERRAL_INVITER_BUCKS
    inviter["referral_earned_energizers"] = inviter.get("referral_earned_energizers", old_count * 2) + REFERRAL_INVITER_ENERGIZERS
    inviter["bucks"] = inviter.get("bucks", 0) + REFERRAL_INVITER_BUCKS
    inviter["energizers"] = inviter.get("energizers", 0) + REFERRAL_INVITER_ENERGIZERS
    inviter["intim_scenes"] = inviter.get("intim_scenes", 0) + REFERRAL_INVITER_SCENES
    inviter["referral_count"] = inviter.get("referral_count", 0) + 1
    user["bucks"] = user.get("bucks", 0) + REFERRAL_INVITEE_BUCKS
    user["referral_pending"] = False
    user["referral_rewarded_at"] = datetime.now().isoformat()
    save_data(user_data)
    return True


def ensure_message_ids(user):
    changed = False
    for message in user.get("history", []):
        if not message.get("id"):
            message["id"] = secrets.token_hex(12)
            changed = True
    if changed:
        save_data(user_data)


def relationship_state(user):
    rel = user.get("relationship") or {}
    trust = max(0, min(100, int(rel.get("trust", 0))))
    respect = max(0, min(100, int(rel.get("respect", 0))))
    stage = 0 if trust < 15 else 1 if trust < 40 else 2 if trust < 70 else 3
    ru = user.get("lang", "ru") == "ru"
    names = ["Знакомство", "Взаимный интерес", "Доверие", "Близкая связь"] if ru else ["Getting acquainted", "Mutual interest", "Trust", "Close bond"]
    return {"trust": trust, "respect": respect, "stage": names[stage]}


def update_relationship(user, text, negative):
    # A daily cap and cooldown prevent farming a relationship by sending many tiny messages.
    rel = user.setdefault("relationship", {})
    today = local_today().isoformat()
    if rel.get("day") != today:
        rel.update(day=today, gains=0)
    if negative or len(set(text.lower().split())) < 4 or rel.get("gains", 0) >= 5:
        return
    now = datetime.now().timestamp()
    if now - rel.get("last_gain", 0) < 600:
        return
    for key in ("trust", "respect"):
        rel[key] = min(100, rel.get(key, 0) + 1)
    rel.update(last_gain=now, gains=rel.get("gains", 0) + 1)


def daily_reset_timestamp():
    tomorrow = local_now().date() + timedelta(days=1)
    return int(datetime.combine(tomorrow, datetime.min.time()).replace(tzinfo=BOT_TZ).timestamp())


def ensure_quests(user):
    # Late arrivals never receive farming missions they cannot finish before midnight.
    changed = daily_quests.ensure(user, local_today().isoformat(), allow_farm=local_now().hour < 16,allowed_events=work_rotation.events(local_today()))
    return changed


def quest_event(user, event, amount=1):
    ensure_quests(user)
    daily_quests.record(user, event, amount)


def quest_chat(user, text):
    if len(set(text.lower().split())) < 4:
        return
    now = datetime.now().timestamp()
    digest = hashlib.sha256(text.strip().casefold().encode()).hexdigest()
    if digest == user.get('quest_chat_hash') or now-user.get('quest_chat_at', 0) < 20:
        return
    user.update(quest_chat_hash=digest, quest_chat_at=now)
    quest_event(user, 'chat')


def daily_quest_state(user):
    if ensure_quests(user):
        save_data(user_data)
    items=daily_quests.snapshot(user,user.get('lang','ru'),has_active_subscription(user))
    if work_v2(user):
        for item in items:
            if item['id']=='mine6':item['title']={'ru':'Собери 6 мозаик','de':'Löse 6 Mosaike'}.get(user.get('lang'),'Solve 6 mosaics')
            if item['id']=='dig4':item['title']={'ru':'Забери находки со склада 4 раза','de':'Hole 4-mal Lagerfunde ab'}.get(user.get('lang'),'Collect depot finds 4 times')
    return {'day':local_today().isoformat(), 'reset_at':daily_reset_timestamp(),
            'bucks_multiplier':2 if has_active_subscription(user) else 1,
            'locked':not (user.get('channel_quest_completed') or user.get('channel_reward_claimed')),
            'channel':None if user.get('channel_reward_claimed') else {'url':CHANNEL_URL,'title':{'ru':'Подпишись на канал · 500 баксов + 1 фото + 1 сцена','de':'Abonniere unseren Kanal'}.get(user.get('lang'),'Subscribe to our channel')},
            'items':items}


async def api_app_task_handler(request):
    _, user, body, err = await _play_request(request)
    if err:
        return err
    if body.get('action')=='channel_check':
        channel=os.getenv('CHANNEL_CHAT_ID','@duel_dev_channel')
        try:
            member=await bot.get_chat_member(channel,int(_))
            status=str(member.status.value if hasattr(member.status,'value') else member.status)
            joined=status in ('creator','administrator','member') or status=='restricted' and bool(getattr(member,'is_member',False))
        except Exception:
            return _app_reply(user,False,'Не удалось проверить подписку. Попробуй позже.')
        if not joined:return _app_reply(user,False,'Подписка пока не найдена. Открой канал и подпишись.')
        if not user.get('channel_reward_claimed'):
            user['bucks']=user.get('bucks',0)+500;user['intim_scenes']=user.get('intim_scenes',0)+1
            photo_wallet.ensure(user);photo_wallet.grant(user,1);user['channel_reward_claimed']=True
        user['channel_quest_completed']=True;save_data(user_data);return _app_reply(user)
    if not (user.get('channel_quest_completed') or user.get('channel_reward_claimed')):return _app_reply(user,False,'Открой задания: подпишись на канал и нажми «Проверить подписку», чтобы открыть задания дня.')
    ensure_quests(user)
    if body.get('day') != local_today().isoformat():
        return _app_reply(user, False, at(user, 'quest_expired'))
    if body.get('action') == 'share':
        quest_event(user, 'share')
        save_data(user_data)
        return _app_reply(user)
    pending=next((q for q in user['daily_quests']['items'] if q['id']==body.get('id')),None)
    if pending and not pending['claimed']:
        definition=daily_quests.BY_ID[pending['id']]
        if definition[3]=='energy' and pending['progress']>=definition[2] and user.get('energy',0)+definition[4]>ENERGY_MAX:
            return _app_reply(user,False,at(user,'quest_energy_full'))
    reward = daily_quests.take(user, body['day'], body.get('id'), has_active_subscription(user))
    if reward is None:
        return _app_reply(user, False, at(user, 'quest_not_ready'))
    kind, amount = reward
    if kind == 'energy':
        user['energy'] = min(ENERGY_MAX,user.get('energy',0)+amount)
        if user['energy'] > 0:
            user['sleep_until'] = None
    else:
        field = {'bucks':'bucks','scenes':'intim_scenes','energizers':'energizers'}[kind]
        user[field] = user.get(field,0)+amount
    save_data(user_data)
    return _app_reply(user)


async def api_app_settings_handler(request):
    _, user, body, err = await _app_request(request)
    if err:
        return err
    if 'initiative_enabled' in body:
        if type(body['initiative_enabled']) is not bool:return _app_reply(user,False,'Invalid setting')
        if body['initiative_enabled'] is False and get_subscription_level(user)!='elite':return _app_reply(user,False,'Отключить сообщения персонажа можно с ELITE')
        user['initiative_enabled']=body['initiative_enabled']
    if 'needs_disabled' in body:
        if type(body['needs_disabled']) is not bool:return _app_reply(user,False,'Invalid setting')
        if get_subscription_level(user)!='elite':return _app_reply(user,False,'Отключить голод и воду можно с ELITE')
        user['needs_disabled']=body['needs_disabled'];user['last_stat_tick']=datetime.now().isoformat()
        if body['needs_disabled']:user.update(satiety=SATIETY_MAX,water=WATER_MAX,water_zero_since=None)
    try:
        preferences=profile_options.validate_preferences(body['preferences'],profile_options.preferences(user)) if 'preferences' in body else None
        race=profile_options.validate_race(body['race']) if 'race' in body else None
    except ValueError as exc:return _app_reply(user,False,str(exc))
    if race is not None and race!=user.get('race','human') and fandom_catalog.selected(user) and not user.get('custom_character'):return _app_reply(user,False,'У готового героя канонический образ.')
    if race is not None and race!=user.get('race','human') and get_subscription_level(user) not in ('super_pro','elite'):
        return _app_reply(user,False,'Изменение внешности · SUPER PRO / ELITE')
    if race is not None and race!=user.get('race','human') and (user.get('photo_pending') or user.get('avatar_job')):return _app_reply(user,False,at(user,'wait_reply'))
    if "lang" in body:
        if body["lang"] not in LANG_BUTTONS:
            return _app_reply(user, False, "Unsupported language")
        user["lang"] = body["lang"]
    if "style" in body:
        if get_subscription_level(user) not in ('super_pro', 'elite'):
            return _app_reply(user, False, get_text(user, 'super_pro_only'))
        if body['style'] not in STYLES or not is_style_unlocked(body['style'], user):
            return _app_reply(user, False, get_text(user, 'style_unavailable'))
        user['style'] = body['style']
        user['reply_choices'] = {}
    if "scene" in body:
        if body["scene"] not in ("phone", "live"):
            return _app_reply(user, False, "Unsupported mode")
        user["scene"] = body["scene"]
    if preferences is not None:user['preferences']=preferences
    if race is not None and race!=user.get('race','human'):
        user['race']=race
        user.pop('identity_reference',None)
    if body.get("tour_seen") is True:
        user["tour_seen"] = True
    save_data(user_data)
    return _app_reply(user)


async def api_app_message_handler(request):
    user_id, user, body, err = await _play_request(request)
    if err:
        return err
    app_unstick(user)
    if user.get("app_pending"):
        return _app_reply(user, False, "Wait for the current reply")
    message = next((m for m in user.get("history", []) if m.get("id") == body.get("id")), None)
    action = body.get("action")
    if not message:
        return _app_reply(user, False, "Message no longer available")
    if action == "react" and message.get("role") == "assistant" and not message.get("card"):
        emoji = body.get("emoji")
        basic = ('❤️','👍','😂','😮','😢','👎')
        premium = ('💖','✨','🔥','🎉')
        if emoji not in basic + premium:
            return _app_reply(user, False, 'Unsupported reaction')
        if emoji in premium and message.get('user_reaction') != emoji and get_subscription_level(user) not in ('pro','super_pro','elite'):
            return _app_reply(user, False, at(user, 'premium_reaction'))
        message['user_reaction'] = None if message.get('user_reaction') == emoji else emoji
        message['reaction_animated'] = bool(message['user_reaction'] in premium)

    elif action in ("edit", "delete") and message.get("role") == "user" and not message.get("card"):
        if action == "delete":
            index = user['history'].index(message)
            del user['history'][index:]
            user['reply_choices'] = {}
            user['location'] = 'unknown'
            user.pop('last_user_message', None)
        else:
            text = body.get("text")
            if not isinstance(text, str) or not text.strip() or len(text) > APP_MESSAGE_MAX_LEN:
                return _app_reply(user, False, "Invalid message")
            index = user['history'].index(message)
            del user['history'][index+1:]
            message.update(content=text.strip(), edited=True)
            for key in ('reaction', 'user_reaction', 'reaction_animated'):
                message.pop(key, None)
            user['reply_choices'] = {}
            user['location'] = 'unknown'
            user.pop('last_user_message', None)
            user['app_pending'] = datetime.now().isoformat()
            asyncio.create_task(app_generate(user_id, user))
    else:
        return _app_reply(user, False, "Action not allowed")
    save_data(user_data)
    return _app_reply(user)


async def main():
    print("🚀 Role Duel запущен!")
    print(f"🧠 Модель: {resolve_model('ai')} | интим-сцены: {resolve_model('intim')}")
    print(f"💾 Данные сохраняются в {os.path.abspath(DATA_FILE)}")
    print(f"👥 Загружено профилей: {len([k for k in user_data if k != '__settings__'])}")
    print(f"💳 Способы оплаты: {', '.join(available_payment_methods())}")
    print(f"🛍 Mini App магазин: {'включён, ' + WEBAPP_URL + '/shop' if WEBAPP_URL else 'выключен (WEBAPP_URL не задан)'}")
    print("✅ БОТ ГОТОВ К РАБОТЕ!")

    for account_id,account in user_data.items():
        if account_id != '__settings__' and isinstance(account,dict):
            retire_blackjack(account)
            if account.get('portrait_pending'):
                account['portrait_pending']=None
                request_character_portrait(account)
    for account in user_data.values():
        if isinstance(account,dict):
            photo_wallet.recover(account)
            if (account.get('broadcast_draft') or {}).get('status')=='sending':account['broadcast_draft']['status']='interrupted'
        if isinstance(account,dict) and account.get('scene_photo_job'):
            refund_scene_photo(account,account['scene_photo_job'].get('id'))
    # Interrupted image jobs never consume the user's energy after a restart.
    for account in user_data.values():
        if isinstance(account, dict) and account.pop('photo_pending', False):
            account['energy'] = min(ENERGY_MAX,account.get('energy',0)+account.pop('photo_reserved',0))
            account['app_pending'] = None
    save_data(user_data)

    # Нативное меню команд Telegram (кнопка "/" рядом с полем ввода) — всегда на русском,
    # т.к. привязано к языку клиента Telegram, а не к языку, выбранному внутри бота.
    # /feed и /work убраны из видимого списка команд — по фидбэку, кормёжка теперь удобнее
    # через кнопку "Магазин" (в т.ч. Mini App), а /work тоже не то, что нужно тыкать часто.
    # Сами команды при этом продолжают работать, если их набрать руками — просто не подсказываются.
    await bot.set_my_commands([
        BotCommand(command="start", description="Открыть приложение"),
        BotCommand(command="help", description="Справка"),
        BotCommand(command="support", description="Поддержка"),
    ])

    if WEBAPP_URL:
        asyncio.create_task(run_webapp_server())
        asyncio.create_task(remove_old_keyboards())
        try:
            # Кнопка слева от поля ввода открывает всё приложение (initData у неё есть, в отличие от reply-клавиатуры).
            await bot.set_chat_menu_button(menu_button=MenuButtonWebApp(text="Открыть", web_app=WebAppInfo(url=f"{WEBAPP_URL}/app")))
        except Exception as e:
            logging.warning(f"set_chat_menu_button: {e}")
    asyncio.create_task(expire_online_rooms())
    asyncio.create_task(check_notifications())
    asyncio.create_task(check_pending_payments())
    await dp.start_polling(bot)


if __name__ == "__main__":
    asyncio.run(main())
